cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_kernel(const half* predictions, const half* targets, half* output, int64_t total_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Compute 1 - predictions[i] * targets[i]
        half prod = predictions[idx] * targets[idx];
        half temp = __hsub(__float2half(1.0f), prod);

        // Clamp to minimum 0
        half result = __hmax(temp, __float2half(0.0f));

        // Store intermediate result
        output[idx] = result;
    }
}

__global__ void reduce_mean_kernel(const half* input, half* output, int64_t n) {
    extern __shared__ half sdata[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Load data into shared memory
    sdata[tid] = (idx < n) ? input[idx] : __float2half(0.0f);
    __syncthreads();

    // Perform reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = __hadd(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Write result for this block to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

torch::Tensor hinge_loss_forward_cuda(const torch::Tensor& predictions, const torch::Tensor& targets) {
    TORCH_CHECK(predictions.dtype() == torch::kFloat16, "predictions must be float16");
    TORCH_CHECK(targets.dtype() == torch::kFloat16, "targets must be float16");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "predictions and targets must have the same shape");

    auto output = torch::empty_like(predictions);
    auto total_elements = predictions.numel();

    if (total_elements == 0) {
        return torch::zeros({}, torch::kFloat16);
    }

    // Launch kernel to compute hinge loss elements
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    hinge_loss_kernel<<<grid_size, block_size>>>(
        predictions.data_ptr<half>(),
        targets.data_ptr<half>(),
        output.data_ptr<half>(),
        total_elements
    );

    // Reduce to mean
    auto result = torch::zeros({}, torch::kFloat16);
    const int reduce_block_size = 256;
    const int reduce_grid_size = (total_elements + reduce_block_size - 1) / reduce_block_size;

    // Use shared memory for reduction
    size_t shared_mem_size = reduce_block_size * sizeof(half);

    reduce_mean_kernel<<<reduce_grid_size, reduce_block_size, shared_mem_size>>>(
        output.data_ptr<half>(),
        result.data_ptr<half>(),
        total_elements
    );

    // Divide by total_elements to get mean
    auto mean_result = result / static_cast<float>(total_elements);

    return mean_result;
}
